<script>
(()=>{
 const writer=document.getElementById('awardWriter'),type=document.getElementById('awardType'),loc=document.getElementById('awardLocale'),title=document.getElementById('awardTitle'),message=document.getElementById('awardMessage'),card=document.getElementById('awardCard');
 const labels={featured:{ar:'كاتب مميّز',en:'Featured Writer',es:'Autor destacado',fr:'Auteur à l’honneur'},editor_choice:{ar:'اختيار التحرير',en:"Editor's Choice",es:'Selección editorial',fr:'Choix de la rédaction'},best_story:{ar:'أفضل قصة',en:'Best Story',es:'Mejor historia',fr:'Meilleure histoire'},contributor:{ar:'مساهم مميّز',en:'Outstanding Contributor',es:'Colaborador destacado',fr:'Contribution remarquable'}};
 const kicker={ar:'تكريم كتّاب سراديب',en:'Saradeeeb Writer Recognition',es:'Reconocimiento de autores',fr:'Distinction des auteurs'};
 function sync(){const o=writer.options[writer.selectedIndex];const name=o?.dataset.name||'اسم الكاتب',username=o?.dataset.username||'username',role=o?.dataset.title||'كاتب في سراديب',avatar=o?.dataset.avatar||'';document.getElementById('awardName').textContent=name;document.getElementById('awardRole').textContent=role;document.getElementById('awardTitlePreview').textContent=title.value||labels[type.value][loc.value]||'تكريم';document.getElementById('awardMessagePreview').textContent=message.value||'';document.getElementById('awardTypeText').textContent=labels[type.value]?.[loc.value]||labels[type.value]?.ar||'تكريم';document.getElementById('awardKicker').textContent=kicker[loc.value]||kicker.en;const profile='<?=e(rtrim(url('/'),'/'))?>/writer/'+username;document.getElementById('awardUrl').textContent=profile.replace(/^https?:\/\//,'');const qr=document.getElementById('awardQr');if(qr)qr.src='https://api.qrserver.com/v1/create-qr-code/?size=220x220&data='+encodeURIComponent(profile);card.dir=loc.value==='ar'?'rtl':'ltr';const a=document.getElementById('awardAvatar');a.innerHTML=avatar?'<img src="'+avatar.replace(/"/g,'')+'" alt="">':'<span>'+name.slice(0,1)+'</span>'}
 [writer,type,loc,title,message].forEach(el=>el&&el.addEventListener(el.tagName==='TEXTAREA'||el.tagName==='INPUT'?'input':'change',sync));sync();
 document.querySelectorAll('[data-award-format]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-award-format]').forEach(x=>x.classList.remove('active'));b.classList.add('active');card.className='award-card-pro award-official-card '+b.dataset.awardFormat});
 function inlineStyles(src,dst){const cs=getComputedStyle(src);let css='';for(const prop of cs)css+=prop+':'+cs.getPropertyValue(prop)+';';dst.setAttribute('style',css);[...src.children].forEach((c,i)=>dst.children[i]&&inlineStyles(c,dst.children[i]))}
 async function imagesToData(root){for(const img of root.querySelectorAll('img')){try{const r=await fetch(img.src);const blob=await r.blob();img.src=await new Promise(ok=>{const fr=new FileReader();fr.onload=()=>ok(fr.result);fr.readAsDataURL(blob)})}catch(e){}}}
 document.getElementById('awardDownload').onclick=async()=>{const status=document.getElementById('awardExportStatus');status.textContent='جارٍ تجهيز البطاقة...';const kind=(card.className.match(/\b(post|square|story|cover|a4|card)\b/)||[])[1]||'post',dims={post:[1080,1350],square:[1080,1080],story:[1080,1920],cover:[1200,630],a4:[2480,3508],card:[1050,600]},[w,h]=dims[kind];const clone=card.cloneNode(true);inlineStyles(card,clone);clone.style.transform='none';await imagesToData(clone);const wrap=document.createElement('div');wrap.setAttribute('xmlns','http://www.w3.org/1999/xhtml');wrap.style.width=card.offsetWidth+'px';wrap.style.height=card.offsetHeight+'px';wrap.appendChild(clone);const xml=new XMLSerializer().serializeToString(wrap),svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+card.offsetWidth+' '+card.offsetHeight+'"><foreignObject width="100%" height="100%">'+xml+'</foreignObject></svg>',url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})),img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);URL.revokeObjectURL(url);const f=document.getElementById('awardExportFormat').value,mime=f==='jpeg'?'image/jpeg':f==='webp'?'image/webp':'image/png';canvas.toBlob(blob=>{if(!blob){status.textContent='تعذر التصدير.';return}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='saradeeeb-writer-award.'+(f==='jpeg'?'jpg':f);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status.textContent='تم تنزيل البطاقة ✓'},mime,.95)};img.onerror=()=>status.textContent='تعذر تجهيز الصورة في هذا المتصفح.';img.src=url};
})();
</script>
<script>
(()=>{const card=document.getElementById('awardCard');if(!card)return;const fit=()=>{const items=[['#awardTitlePreview',52],['#awardName',34],['#awardMessagePreview',17]];items.forEach(([selector,max])=>{const el=card.querySelector(selector);if(!el)return;el.style.fontSize=max+'px';while((el.scrollHeight>el.clientHeight||card.scrollHeight>card.clientHeight)&&parseFloat(el.style.fontSize)>12)el.style.fontSize=(parseFloat(el.style.fontSize)-1)+'px'})};window.addEventListener('resize',fit);document.querySelectorAll('#awardTitle,#awardMessage,#awardWriter').forEach(el=>el.addEventListener('input',()=>requestAnimationFrame(fit)));requestAnimationFrame(fit);card.querySelectorAll('img').forEach(img=>img.addEventListener('load',fit))})();
</script>
